"""Offline ADB and length-prefixed plist exchange parsing."""
import io
import plistlib
import struct
from xml.parsers.expat import ExpatError


def checksum(data):
    total=0
    for byte in data:
        total=(total+byte)&0xffffffff
    return total


def send_connect():
    command=0x4e584e43
    identity=b'host::zgrab2'
    return struct.pack('<6I',command,0x01000000,4096,len(identity),
                       checksum(identity),command^0xffffffff)+identity


def send_close():
    command=0x45534c43
    return struct.pack('<6I',command,0,0,0,0,command^0xffffffff)


def read_adb_response(data):
    if len(data)<24:
        raise ValueError('short ADB header')
    command,arg0,arg1,length,check,magic=struct.unpack('<6I',data[:24])
    if command^magic!=0xffffffff:
        raise ValueError('bad ADB header')
    if command==0x4e584e43:
        banner=data[24:].decode('utf-8')
        version=f'{(arg0>>16)&255}.{(arg0>>8)&255}.{arg0&255}'
        return ('CNXN',version,banner)
    return ('AUTH',arg0,arg1,data[24:].hex())


GET_VERSION=0
GET_PRODUCT_NAME=1
USBMUXD_COMMANDS={
    GET_VERSION:('ProductVersion','GetValue'),
    GET_PRODUCT_NAME:('ProductName','GetValue')}


def get_value_request(kind):
    key,request=USBMUXD_COMMANDS[kind]
    value=plistlib.dumps({'Key':key,'Label':'usbmuxd','ProtocolVersion':'2',
                         'Request':request},fmt=plistlib.FMT_XML,sort_keys=False)
    return struct.pack('>I',len(value))+value


def get_plists(stream,kind):
    header=stream.read(4)
    size=struct.unpack('>I',header)[0]
    if size==0 or size>65532:
        raise ValueError('invalid plist length')
    body=stream.read(size)
    value=plistlib.loads(body)
    expected=USBMUXD_COMMANDS[kind][0]
    if (type(value) is not dict or set(value)!={'Key','Request','Value'}
            or value['Key']!=expected or value['Request']!='GetValue'
            or type(value['Value']) is not str or not value['Value']):
        raise ValueError('invalid GetValue response')
    return value['Value']


def send_messages(data):
    stream=io.BytesIO(data)
    version=get_plists(stream,GET_VERSION)
    product=get_plists(stream,GET_PRODUCT_NAME)
    if stream.read(1):
        raise ValueError('trailing plist frame')
    return ('sync',version,product)


def signature(kind,data):
    try:
        if kind=='tcp':
            if data:
                raise ValueError('TCP payload must be empty')
            return ('tcp',)
        if kind=='adb':
            return read_adb_response(data)
        return send_messages(data)
    except (ValueError,UnicodeError,OverflowError,TypeError,plistlib.InvalidFileException,ExpatError):
        return None


def probe_script(kind):
    import base64
    encode=lambda b:base64.b64encode(b).decode('ascii')
    if kind=='tcp':
        return [],[]
    if kind=='adb':
        return [encode(send_connect())],[encode(send_close())]
    return [encode(get_value_request(GET_VERSION)),encode(get_value_request(GET_PRODUCT_NAME))],[]
