"""Offline ADB and length-prefixed plist exchange parsing.

The adapters only decode bytes that were handed to them: no socket is opened
and no device is contacted.  Malformed wire data is reported as ``None`` so a
census row can stay a valid record with an unknown service state.
"""
import base64
import io
import plistlib
import struct
from xml.parsers.expat import ExpatError

CNXN=0x4e584e43
AUTH=0x48545541
CLSE=0x45534c43
MAGIC=0xffffffff
MAX_ADB_BODY=65535
MAX_FRAME=65532

GET_VERSION=0
GET_PRODUCT_NAME=1
USBMUXD_COMMANDS={
    GET_VERSION:('ProductVersion','GetValue'),
    GET_PRODUCT_NAME:('ProductName','GetValue')}


def checksum(data):
    total=0
    for byte in data:
        total=(total+byte)&0xffffffff
    return total


def packet(command,arg0,arg1,body):
    """One ADB style packet: six little endian words plus the body."""
    return (struct.pack('<6I',command,arg0,arg1,len(body),checksum(body),
                         command^MAGIC)+body)


def send_connect():
    return packet(CNXN,0x01000000,4096,b'host::zgrab2')


def send_close():
    return packet(CLSE,0,0,b'')


def read_adb_response(data):
    """Parse exactly one ADB packet into its open signature."""
    if len(data)<24:
        raise ValueError('short ADB header')
    command,arg0,arg1,length,check,magic=struct.unpack('<6I',data[:24])
    if command^magic!=MAGIC:
        raise ValueError('bad ADB magic')
    if length>MAX_ADB_BODY:
        raise ValueError('bad ADB length')
    body=data[24:]
    if len(body)!=length:
        raise ValueError('bad ADB body length')
    if checksum(body)!=check:
        raise ValueError('bad ADB checksum')
    if command==CNXN:
        banner=body.decode('utf-8')
        version='%d.%d.%d'%((arg0>>16)&255,(arg0>>8)&255,arg0&255)
        return ('CNXN',version,banner)
    if command==AUTH:
        return ('AUTH',arg0,arg1,body)
    raise ValueError('unsupported ADB command')


def frame(body):
    """One length prefixed plist frame."""
    return struct.pack('>I',len(body))+body


def get_value_request(kind):
    key,request=USBMUXD_COMMANDS[kind]
    value=plistlib.dumps({'Key':key,'Label':'usbmuxd','ProtocolVersion':'2',
                          'Request':request},fmt=plistlib.FMT_XML,sort_keys=False)
    return frame(value)


def read_frame(stream):
    header=stream.read(4)
    if len(header)!=4:
        raise ValueError('short plist frame')
    size=struct.unpack('>I',header)[0]
    if size<1 or size>MAX_FRAME:
        raise ValueError('invalid plist length')
    body=stream.read(size)
    if len(body)!=size:
        raise ValueError('truncated plist frame')
    return body


def get_plists(stream,kind):
    body=read_frame(stream)
    value=plistlib.loads(body)
    expected=USBMUXD_COMMANDS[kind][0]
    if (type(value) is not dict or set(value)!={'Key','Request','Value'}
            or value['Key']!=expected or value['Request']!='GetValue'
            or type(value['Value']) is not str or not value['Value']):
        raise ValueError('invalid GetValue response')
    return value['Value']


def read_sync(data):
    """Parse exactly two length prefixed plist frames into a sync signature."""
    stream=io.BytesIO(data)
    version=get_plists(stream,GET_VERSION)
    product=get_plists(stream,GET_PRODUCT_NAME)
    if stream.read(1):
        raise ValueError('trailing plist frame')
    return ('sync',version,product)


def signature(kind,data):
    """Parsed open signature of one application payload, or ``None``."""
    try:
        if kind=='tcp':
            if data:
                raise ValueError('TCP payload must be empty')
            return ('tcp',)
        if kind=='adb':
            return read_adb_response(data)
        return read_sync(data)
    except (ValueError,UnicodeError,OverflowError,TypeError,RecursionError,
            struct.error,plistlib.InvalidFileException,ExpatError):
        return None


def probe_script(kind):
    """Base64 packet arrays certifying the outbound probe of one service."""
    encode=lambda b:base64.b64encode(b).decode('ascii')
    if kind=='tcp':
        return [],[]
    if kind=='adb':
        return [encode(send_connect())],[encode(send_close())]
    return [encode(get_value_request(GET_VERSION)),
            encode(get_value_request(GET_PRODUCT_NAME))],[]
