"""Campaign census extension point.

The census turns reconciled records into per query lease evidence: the
internal and external discovery roles, the unresolved low targets, the
causal application census and the frozen activity of every follow-up
request.
"""

from common import addresses
from ledger import (ATTEMPT,EVENT,LEASE,PAYLOAD,PROBE,RESPONDER,RESULT,
                     SERVICE,TARGET,TYPE)
from protocols import signature


def lease_states(live,context,at):
    """Derive the per lease discovery roles and quarantine state at a query."""
    states={}
    for lease_id in context['leases']:
        states[lease_id]={'alias':False,'internal':set(),'external':set(),
                          'witness':{}}
    for record in live:
        if record[TYPE]!='icmp':
            continue
        lease=record[LEASE]
        entry=states[lease]
        target=record[TARGET]
        responder=record[RESPONDER]
        result=record[RESULT]
        if result=='timeout':
            continue
        planned,is_canary=context['lookup'][(lease,record[PROBE])]
        if is_canary:
            if result=='echo' and responder==target:
                entry['alias']=True
            continue
        if result=='echo' and responder==target:
            role='internal'
        elif responder!=target:
            role='external'
        else:
            continue
        entry[role].add(responder)
        key=(role,responder)
        previous=entry['witness'].get(key)
        if previous is None or record[EVENT]<previous:
            entry['witness'][key]=record[EVENT]
    for lease_id,lease in context['leases'].items():
        entry=states[lease_id]
        active=lease['start']<=at<lease['end']
        conflicts=sorted(entry['internal']&entry['external'])
        if not active:
            entry.update({'state':'inactive','conflicts':[],'internal':set(),
                          'external':set(),'witness':{},'active':False})
            continue
        if entry['alias']:
            state='alias'
        elif conflicts:
            state='conflict'
        else:
            state='usable'
        if state=='usable':
            clean_internal=entry['internal']
            clean_external=entry['external']
            witness=entry['witness']
        else:
            clean_internal=set()
            clean_external=set()
            witness={}
        entry.update({'state':state,'conflicts':conflicts,
                      'internal':clean_internal,'external':clean_external,
                      'witness':witness,'active':True})
    return states


def application_groups(live,states,context):
    """Group the eligible application rows and count the unbound ones."""
    groups={}
    unbound=0
    for record in live:
        if record[TYPE]!='app':
            continue
        lease=record[LEASE]
        state=states[lease]
        target=record[TARGET]
        service=record[SERVICE]
        eligible=False
        if state['state']=='usable':
            if target in state['internal']:
                role='internal'
            elif target in state['external']:
                role='external'
            else:
                role=None
            if role is not None:
                witness=state['witness'].get((role,target))
                if witness is not None and witness<=record[EVENT]:
                    eligible=True
        if eligible:
            groups.setdefault((lease,target,service),[]).append(record)
        else:
            unbound+=1
    return groups,unbound


def service_status(groups,context):
    """Decide the service state of every eligible address and service."""
    status={}
    errors={}
    kinds=context['services']
    for key,rows in groups.items():
        lease,target,service=key
        latest=max(row[ATTEMPT] for row in rows)
        rows=[row for row in rows if row[ATTEMPT]==latest]
        outcomes=set(row[RESULT] for row in rows)
        if outcomes=={'open'}:
            signatures=set()
            broken=0
            for row in rows:
                parsed=signature(kinds[service],row[PAYLOAD])
                if parsed is None:
                    broken+=1
                else:
                    signatures.add(parsed)
            status[key]='open' if not broken and len(signatures)==1 else 'unknown'
            if broken:
                marker=(lease,service)
                errors[marker]=errors.get(marker,0)+broken
        elif outcomes=={'closed'}:
            status[key]='closed'
        else:
            status[key]='unknown'
    return status,errors


def lease_report(context,states,status,errors,low):
    """Assemble the per lease report of one snapshot."""
    report=[]
    for lease_id in sorted(context['leases']):
        state=states[lease_id]
        services=[]
        for service_id in sorted(context['services']):
            internal=state['internal']
            external=state['external']
            internal_open=sorted(a for a in internal
                                 if status.get((lease_id,a,service_id))=='open')
            internal_closed=sorted(a for a in internal
                                   if status.get((lease_id,a,service_id))=='closed')
            external_open=sorted(a for a in external
                                 if status.get((lease_id,a,service_id))=='open')
            external_closed=sorted(a for a in external
                                   if status.get((lease_id,a,service_id))=='closed')
            if external and len(external_closed)==len(external):
                internal_only=internal_open
            else:
                internal_only=[]
            services.append({'id':service_id,
                             'internal_open':addresses(internal_open),
                             'internal_closed':addresses(internal_closed),
                             'external_open':addresses(external_open),
                             'external_closed':addresses(external_closed),
                             'internal_only':addresses(internal_only),
