        if state['active']:
            unresolved=low[lease_id]-state['internal']-state['external']
        else:
            unresolved=set()
        report.append({'lease':lease_id,'state':state['state'],
                       'conflicts':addresses(state['conflicts']),
                       'internal':addresses(state['internal']),
                       'external':addresses(state['external']),
                       'unresolved':addresses(unresolved),
                       'services':services})
